			<p className="mt-2 text-stone-500">
				No match exists with the identifier “{matchId}”.
			</p>
			<Link
				className="mt-6 inline-flex text-amber-300 hover:text-amber-200"
				to="/matches"
			>
				Return to matches →
			</Link>
		</section>
	);
}

